/* features: 33 float; out_probabilities: 2 float veya NULL.
   Dönüş: en olası sınıfın indeksi. */
static int human_detector_predict(const float* features, float* out_probabilities) {
    float votes[2] = {0};
    human_detector_tree_0(features, votes);
    human_detector_tree_1(features, votes);
    human_detector_tree_2(features, votes);
    human_detector_tree_3(features, votes);
    human_detector_tree_4(features, votes);
    human_detector_tree_5(features, votes);
    human_detector_tree_6(features, votes);
    human_detector_tree_7(features, votes);
    human_detector_tree_8(features, votes);
    human_detector_tree_9(features, votes);

    int best_class = 0;
    float max_prob = -1.0f;
    for (int c = 0; c < 2; c++) {
        float p = votes[c] / (float)10;
        if (out_probabilities) out_probabilities[c] = p;
        if (p > max_prob) {
            max_prob = p;
            best_class = c;
        }
    }
    return best_class;
}

